/** One streaming ScanQuad joined to an exact point lookup through a prepared repository query. */
@State(Scope.Thread)
@Threads(1)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.NANOSECONDS)
@Warmup(iterations = 4, time = 1)
@Measurement(iterations = 5, time = 1)
@Fork(value = 3, jvmArgsAppend = { "-Drdf4j.lmdb.parallel.enabled=false",
		"-Drdf4j.lmdb.irKernelParallel.enabled=false" })
public class LmdbPreparedScanQuadBenchmark {

	private static final int ROWS = 32768;
	private static final String STRATEGY = "irKernelInterpreted";
	private static final String QUERY = """
			SELECT ?o WHERE {
			  GRAPH <urn:g> { <urn:s> <urn:p> ?o . <urn:s> <urn:q> ?o }
			}
			""";
	private SailRepository repository;
	private long expectedChecksum;

	@Setup
	public void setUp() {
		var config = new LmdbStoreConfig("spoc,posc").setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(false)
				.setForceSync(false);
		repository = new SailRepository(new LmdbStore(config));
		try (var connection = repository.getConnection()) {
			var values = connection.getValueFactory();
			var subject = values.createIRI("urn:s");
			var graph = values.createIRI("urn:g");
			var left = values.createIRI("urn:p");
			var right = values.createIRI("urn:q");
			connection.begin();
			for (int i = 0; i < ROWS; i++) {
				var object = values.createIRI("urn:object:" + i);
				connection.add(subject, left, object, graph);
				connection.add(subject, right, object, graph);
				expectedChecksum += object.hashCode();
			}
			connection.commit();
		}

		List<String> selected = new ArrayList<>();
		LmdbNativeDispatchLoop.observeSelections((target, label, id, record) -> {
			if (record.point() == LmdbNativeDecisionPoint.ROW) {
				selected.add(id);
			}
		});
		try {
			preparedGraphJoin();
		} finally {
			LmdbNativeDispatchLoop.observeSelections(null);
		}
		if (!selected.equals(List.of(STRATEGY))) {
			throw new IllegalStateException("Expected one interpreted row kernel, found " + selected);
		}
	}

	@Benchmark
	@OperationsPerInvocation(ROWS)
	public long preparedGraphJoin() {
		try (var connection = repository.getConnection()) {
			var query = (SailTupleQuery) connection.prepareTupleQuery(QUERY);
			query.setIncludeInferred(false);
			query.setForcedLmdbExecutionStrategy(STRATEGY);
			long checksum = 0;
			int count = 0;
			try (var rows = query.evaluate()) {
				while (rows.hasNext()) {
					checksum += rows.next().getValue("o").hashCode();
					count++;
				}
			}
			if (count != ROWS || checksum != expectedChecksum) {
				throw new IllegalStateException(
						"Unexpected graph join output: " + count + " rows, checksum " + checksum);
			}
			return checksum;
		}
	}

	@TearDown
	public void tearDown() {
		repository.shutDown();
	}
}
